INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Innocent spouse relief under Section 6015
(3, 'Individual Taxation: Filing/Credits', 'Patel filed a joint return with her husband for 2025. After their divorce in 2026, the IRS assessed $45,000 in additional tax due to $120,000 of unreported income from her husband''s side business. Patel had no knowledge of and no reason to know about this income. Under Section 6015, which form of relief most directly addresses Patel''s situation?', '["Traditional innocent spouse relief under Section 6015(b), which relieves the requesting spouse from liability attributable to the other spouse''s erroneous items", "Separation of liability under Section 6015(c), which requires the spouses to remain married and living together", "Equitable relief under Section 6015(f), which is available only when the understatement is below $10,000", "Injured spouse allocation, which divides the assessed deficiency equally between both spouses"]'::jsonb, 0, 'Under IRC Section 6015(b), a requesting spouse may be relieved of liability for an understatement attributable to the other spouse''s erroneous items when the requesting spouse did not know and had no reason to know of the understatement. Patel meets these requirements because the unreported income was entirely her husband''s. Separation of liability under Section 6015(c) does not require spouses to remain married — it is actually available to divorced or separated taxpayers.', 'hard', 4),

-- Q2: medium / L2 — Additional standard deduction for age 65+ and blind (unmarried)
(3, 'Individual Taxation: Filing/Credits', 'Henderson, a single taxpayer age 67 who is legally blind, has $30,000 in wage income for 2025. Henderson does not itemize deductions. What is Henderson''s total standard deduction for 2025?', '["$15,000", "$19,000", "$18,200", "$17,000"]'::jsonb, 1, 'Under IRC Section 63(f), an unmarried taxpayer receives an additional standard deduction of $2,000 for each qualifying condition — being age 65 or older and being blind. Henderson qualifies for both, adding $4,000 ($2,000 + $2,000) to the base Single standard deduction of $15,000, totaling $19,000. A common error is using the $1,600 married additional amount, which would yield $18,200 — but that figure applies only to married taxpayers.', 'medium', 2),

-- Q3: easy / L1 — Joint and several liability on MFJ
(3, 'Individual Taxation: Filing/Credits', 'What does joint and several liability mean on a married filing jointly return?', '["Each spouse is liable only for the tax on their own income", "Liability is split equally between both spouses", "The IRS may collect the entire tax from either spouse individually", "Only the higher-earning spouse is liable for the total tax"]'::jsonb, 2, 'Under IRC Section 6013(d)(3), when a married couple files jointly, both spouses are jointly and severally liable for the entire tax due on the return. The IRS can collect the full amount from either spouse, regardless of who earned the income. The liability is not limited to each spouse''s proportionate share — either spouse can be held responsible for the full amount.', 'easy', 1),

-- Q4: medium / L3 — Tiebreaker: longer residence beats higher AGI
(3, 'Individual Taxation: Filing/Credits', 'After their divorce, Walker and Morgan share custody of their 7-year-old daughter, Lily. During 2025, Lily lived with Walker for 183 nights and with Morgan for 182 nights. Walker has AGI of $52,000 and Morgan has AGI of $78,000. Neither parent has signed Form 8332. Under the tiebreaker rules, which parent may claim Lily as a qualifying child?', '["Morgan, because Morgan has the higher AGI", "Either parent may claim the child since the residency difference is only one night", "Walker and Morgan must alternate the claim in even and odd years", "Walker, because Lily lived with Walker for the longer period during the year"]'::jsonb, 3, 'Under IRC Section 152(c)(4)(B), when both parents can claim a child but do not file jointly, the parent with whom the child lived for the longer period claims the dependent. Walker had Lily for 183 nights versus Morgan''s 182, so Walker claims Lily regardless of AGI. The higher-AGI tiebreaker applies only when the child lived with each parent for an equal amount of time.', 'medium', 3),

-- Q5: easy / L1 — Citizenship/residency test for dependents
(3, 'Individual Taxation: Filing/Credits', 'Under Section 152, which citizenship or residency status must a dependent meet to be claimed on a U.S. federal tax return?', '["U.S. citizen, U.S. national, U.S. resident alien, or resident of Canada or Mexico", "U.S. citizen or permanent resident only", "Citizen of any country with a U.S. tax treaty", "U.S. citizen, U.S. resident alien, or resident of any North American country"]'::jsonb, 0, 'Under IRC Section 152(b)(3), a dependent must be a U.S. citizen, U.S. national, U.S. resident alien, or a resident of Canada or Mexico. This citizenship test applies to both qualifying children and qualifying relatives. The test does not extend to all treaty countries or all North American nations — it is specifically limited to the United States, Canada, and Mexico.', 'easy', 1),

-- Q6: medium / L2 — Temporary absence rule for residency test (boarding school)
(3, 'Individual Taxation: Filing/Credits', 'Martinez, a single mother, sends her 15-year-old son Diego to a boarding school in another state from September through May (9 months). Diego returns home for summer break and holidays. Martinez pays all household costs and provides more than half of Diego''s support. Does Diego meet the residency test for a qualifying child?', '["No, because Diego lived away from the home for more than half the year", "Yes, because temporary absences for education count as time lived in the home", "Yes, but only if the boarding school is in the same state as Martinez''s home", "No, because the child must physically sleep in the taxpayer''s home for more than 183 nights"]'::jsonb, 1, 'Under IRC Section 152(c)(1)(B) and related regulations, temporary absences due to education, illness, business, military service, or detention are treated as time the child lived with the taxpayer. Diego''s 9-month boarding school absence is a temporary absence for education, so he is treated as living with Martinez for the entire year. A common misconception is that the child must be physically present more than half the year.', 'medium', 2),

-- Q7: medium / L3 — Foster child qualifying under relationship test
(3, 'Individual Taxation: Filing/Credits', 'The Dalton family took in Marcus (age 12), a foster child placed by an authorized agency in January 2025. Marcus lived with them the entire year. The Daltons provided all financial support. Marcus is not biologically related to the Daltons. Analyze whether Marcus qualifies as a qualifying child for dependency purposes.', '["No, because Marcus is not biologically or legally related to the Daltons", "No, because foster children only qualify as qualifying relatives, not qualifying children", "Yes, because an eligible foster child placed by an authorized agency satisfies the relationship test for a qualifying child", "Yes, but only if the Daltons formally adopt Marcus before year-end"]'::jsonb, 2, 'Under IRC Section 152(f)(1)(C), an eligible foster child placed by an authorized placement agency or by court order satisfies the relationship test for a qualifying child. Marcus meets all other tests: under 19, lived with the Daltons all year, and did not provide his own support. A common error is believing only biological or adopted children qualify — foster children placed by authorized agencies are explicitly included.', 'medium', 3),

-- Q8: medium / L3 — Social Security excluded from qualifying relative gross income test
(3, 'Individual Taxation: Filing/Credits', 'Nelson provides 60% of total support for his elderly mother, who lives with him year-round. She received $18,000 in Social Security benefits and $4,800 in pension income during 2025. Her provisional income is low enough that none of the Social Security is taxable. Analyze whether she meets the gross income test for a qualifying relative.', '["No, because her total receipts of $22,800 exceed the $5,050 gross income limit", "No, because Social Security benefits are always included in gross income for dependency purposes", "Yes, but only because she is a parent and parents are exempt from the gross income test", "Yes, because nontaxable Social Security benefits are excluded from gross income, leaving only $4,800 below the $5,050 threshold"]'::jsonb, 3, 'Under IRC Section 152(d)(1)(B), a qualifying relative must have gross income below $5,050 (2025). Gross income under Section 61 includes only taxable income. When Social Security benefits are fully nontaxable under Section 86, they are excluded from gross income. Nelson''s mother''s gross income is only the $4,800 pension, which is below $5,050. A common error is including the full Social Security amount regardless of taxability.', 'medium', 3),

-- Q9: easy / L2 — Permanently disabled child has no age limit
(3, 'Individual Taxation: Filing/Credits', 'Carter, age 35 and permanently and totally disabled, lives with his parents year-round. Carter earned $2,000 from a sheltered workshop and did not provide more than half of his own support. Can Carter''s parents claim him as a qualifying child under Section 152?', '["Yes, because there is no age limit for a qualifying child who is permanently and totally disabled", "No, because Carter exceeds the age limit of 24 for a qualifying child", "No, because Carter has earned income, which disqualifies him as a dependent", "Yes, but only if Carter''s earned income is below $5,050"]'::jsonb, 0, 'Under IRC Section 152(c)(3)(B), a qualifying child who is permanently and totally disabled has no age restriction — the under-19 or under-24 student age test does not apply. Carter lives with his parents, did not provide more than half of his own support, and meets the relationship test. Earned income does not disqualify a qualifying child because there is no gross income test for qualifying children.', 'easy', 2),

-- Q10: easy / L1 — Form 2120 for multiple support agreement
(3, 'Individual Taxation: Filing/Credits', 'Which IRS form is used to document a multiple support agreement?', '["Form 8332", "Form 2120", "Form 8962", "Form 8880"]'::jsonb, 1, 'Under IRC Section 152(d)(3), Form 2120 (Multiple Support Declaration) is used when a group of taxpayers collectively provides more than 50% of a person''s support but no single taxpayer provides more than 50%. Each eligible member contributing more than 10% must sign Form 2120 waiving their claim. Form 8332 is the release of dependency by a custodial parent, a different mechanism.', 'easy', 1),

-- Q11: medium / L3 — QSS disqualified upon remarriage
(3, 'Individual Taxation: Filing/Credits', 'Watkins''s husband died in 2024. In 2025, Watkins maintains a home for her 10-year-old dependent son and has not remarried. In October 2026, Watkins marries Reynolds. Analyze why Watkins can file as Qualifying Surviving Spouse for 2025 but not for 2026.', '["QSS status is available for only one year after the spouse''s death", "Watkins''s son must be under age 5 to qualify for QSS in the second year", "Remarriage before the end of the tax year disqualifies the taxpayer from QSS status", "QSS requires the taxpayer to maintain the same home where the deceased spouse lived"]'::jsonb, 2, 'Under IRC Section 2(a), a surviving spouse may file as QSS for two years after the year of death, provided the taxpayer has not remarried before year-end, maintains a home for a dependent child, and pays more than half the home''s costs. In 2025 Watkins meets all requirements. In 2026, her October remarriage disqualifies her because she is no longer unmarried at year-end. QSS is available for two years, not one.', 'medium', 3),

-- Q12: medium / L2 — Cost of maintaining a home for HOH (included vs excluded expenses)
(3, 'Individual Taxation: Filing/Credits', 'Franklin, a single parent, maintains a home where he and his 10-year-old daughter live all year. The total qualifying home costs are $28,000, consisting of $14,000 rent, $4,200 utilities, $5,800 food consumed at home, and $4,000 insurance. Franklin pays $18,000 of these costs and his parents contribute $10,000. He also spends $6,000 on clothing and $3,000 on medical care for his daughter. Does Franklin qualify as Head of Household?', '["No, because Franklin does not pay 100% of the home costs", "No, because the clothing and medical expenses should be included, raising the total beyond what Franklin covers at 50%", "Yes, but only if Franklin''s parents do not also claim his daughter as a dependent", "Yes, because Franklin pays $18,000 of the $28,000 qualifying home costs (64%), exceeding 50%"]'::jsonb, 3, 'Under IRC Section 2(b), HOH requires paying more than half the cost of maintaining the home. Qualifying costs include rent, mortgage interest, property taxes, utilities, food eaten in the home, and insurance. Clothing, education, medical care, and transportation are excluded. Franklin pays $18,000 of $28,000 in qualifying costs (64%), exceeding 50%. A common error is including non-qualifying expenses like clothing and medical care.', 'medium', 2),

-- Q13: medium / L3 — Joint return test exception (refund-only filing)
(3, 'Individual Taxation: Filing/Credits', 'Kendra, age 19 and not a student, is claimed as a dependent by her parents. Kendra married Luis in December 2025. Neither has a tax liability if they file separately, but Luis had $800 withheld from wages. They want to file jointly solely to claim a refund of Luis''s withholding. Can Kendra''s parents still claim her as a dependent?', '["Yes, because the joint return test has an exception when the return is filed solely to claim a refund and neither spouse would owe tax filing separately", "No, because a married dependent who files a joint return can never be claimed by another taxpayer", "Yes, but only if Kendra''s gross income is below $5,050", "No, because marriage automatically terminates a parent''s right to claim a child as a dependent"]'::jsonb, 0, 'Under IRC Section 152(b)(2), a dependent generally cannot file a joint return. However, an exception applies when the joint return is filed only to claim a refund of withheld taxes or estimated payments and neither spouse has a tax liability filing separately. Since Kendra and Luis meet both conditions, Kendra''s parents retain the ability to claim her as a dependent.', 'medium', 3),

-- Q14: medium / L2 — Unrelated person as qualifying relative (member of household full year)
(3, 'Individual Taxation: Filing/Credits', 'Gomez, a single taxpayer, provides 100% of financial support for his longtime friend Parker, who lives in Gomez''s home for the entire year. Parker is not related to Gomez by blood, marriage, or adoption. Parker''s only income is $3,200 from a part-time job. Can Gomez claim Parker as a qualifying relative?', '["No, because Parker is not related to Gomez by blood, marriage, or adoption", "Yes, because an unrelated person who lives with the taxpayer for the entire year as a member of the household can qualify under the relationship test", "No, because the qualifying relative rules require a formal legal guardianship arrangement", "Yes, but only if Parker is a minor under age 18"]'::jsonb, 1, 'Under IRC Section 152(d)(2)(H), a person who lives with the taxpayer as a member of the household for the entire year satisfies the relationship test for a qualifying relative, even without a familial connection. Parker also meets the other tests: gross income of $3,200 is below $5,050, Gomez provides over 50% support, and Parker is not a qualifying child of anyone. Unrelated individuals can qualify through the member-of-household provision.', 'medium', 2),

-- Q15: medium / L2 — Saver''s Credit eligibility and calculation
(3, 'Individual Taxation: Filing/Credits', 'Mitchell, a single taxpayer age 28 who is not a full-time student, has AGI of $22,000 in 2025. Mitchell contributes $1,500 to a traditional IRA and is not claimed as a dependent. Under Section 25B, what is Mitchell''s Retirement Savings Contributions Credit?', '["$150 (10% of $1,500)", "$300 (20% of $1,500)", "$750 (50% of $1,500)", "$1,000 (the maximum credit for single filers)"]'::jsonb, 2, 'Under IRC Section 25B, the Saver''s Credit provides 50%, 20%, or 10% of retirement contributions up to $2,000, depending on AGI and filing status. For 2025, a single filer with AGI at or below approximately $23,750 receives the maximum 50% rate. Mitchell''s $22,000 AGI qualifies for 50%, so the credit is $750 (50% x $1,500). A common error is applying the lower 10% or 20% rate that applies at higher AGI levels.', 'medium', 2),

-- Q16: medium / L3 — MFS disqualification from multiple credits and deductions
(3, 'Individual Taxation: Filing/Credits', 'Collins and her husband are married and considering filing separately for 2025. Collins has $45,000 in wages, paid $2,000 in student loan interest, and has one qualifying child. Analyze which tax benefits Collins would lose by choosing Married Filing Separately instead of Married Filing Jointly.', '["Only the Earned Income Credit would be disallowed", "Only the student loan interest deduction would be disallowed", "Collins would lose the Child Tax Credit and the standard deduction", "Collins would lose the Earned Income Credit, the student loan interest deduction, and education credits"]'::jsonb, 3, 'Under IRC Sections 32(d), 221(e)(1), and 25A(g)(6), taxpayers filing MFS are ineligible for the Earned Income Credit, the student loan interest deduction, and education credits (AOTC and LLC). The Child Tax Credit and standard deduction remain available under MFS. Collins would lose three significant tax benefits by filing separately. A common error is believing only one benefit is affected — MFS triggers broad disqualifications.', 'medium', 3),

-- Q17: hard / L4 — Parent-priority tiebreaker over higher-AGI grandparent
(3, 'Individual Taxation: Filing/Credits', 'Rosa (AGI $35,000) lives with her mother Helen (AGI $95,000) and Rosa''s 4-year-old son Leo in Helen''s home for the entire year. Rosa provides 40% of Leo''s support and Helen provides 60%. Both meet the qualifying child tests for Leo. Evaluate who is entitled to claim Leo under the tiebreaker rules and explain why AGI does not control the outcome.', '["Rosa claims Leo because the parent-priority tiebreaker gives a parent the right to claim the child over any non-parent, regardless of AGI", "Helen claims Leo because she has the higher AGI and provides more than 50% of Leo''s support", "Helen claims Leo because Leo lives in her home and she pays the majority of household expenses", "Neither can claim Leo because the tiebreaker rules only apply when there are exactly two competing claims"]'::jsonb, 0, 'Under IRC Section 152(c)(4)(A), when both a parent and a non-parent are eligible to claim a child, the parent has priority regardless of AGI. Rosa is Leo''s parent, so she prevails over Helen even though Helen has higher AGI and provides more support. The AGI tiebreaker under Section 152(c)(4)(B) applies only between two parents or two non-parents. Parent status always overrides AGI.', 'hard', 4),

-- Q18: medium / L2 — Dependent filing requirement (unearned income exceeds threshold)
(3, 'Individual Taxation: Filing/Credits', 'Briggs, age 16, is claimed as a dependent on her parents'' return. In 2025, Briggs earned $400 from babysitting and received $1,800 in interest from a savings account. Under the dependent filing rules, must Briggs file her own federal income tax return?', '["No, because her total income of $2,200 is below the Single standard deduction of $15,000", "Yes, because her unearned income of $1,800 exceeds $1,350, triggering a filing requirement for dependents", "No, because dependents under age 18 are never required to file their own returns", "Yes, but only because her earned income exceeds $400"]'::jsonb, 1, 'Under IRC Section 6012, a dependent must file a return if unearned income exceeds $1,350 (2025), earned income exceeds the standard deduction amount, or gross income exceeds the larger of $1,350 or earned income plus $450. Briggs''s $1,800 in unearned income exceeds $1,350, so she must file. A common error is applying the full $15,000 standard deduction as the filing threshold — dependents have lower thresholds.', 'medium', 2),

-- Q19: hard / L4 — Executor filing MFJ for deceased spouse in year of death
(3, 'Individual Taxation: Filing/Credits', 'Grant died on March 15, 2025. Grant''s executor, Phillips, is considering filing options for Grant''s final return. Grant''s surviving spouse Taylor earned $90,000 and has not remarried. Grant earned $25,000 before death. The couple has no dependents. Evaluate which filing status produces the most favorable result and identify the key condition for a joint return.', '["Taylor must file as Single because Grant is deceased, and Phillips files a separate return for Grant", "Phillips can only file MFS for Grant because a deceased taxpayer cannot consent to a joint return", "Phillips and Taylor may file MFJ for 2025 combining both incomes and using the $30,000 standard deduction, provided Taylor has not remarried by year-end", "Taylor should file as Qualifying Surviving Spouse for 2025 to receive the same brackets as MFJ"]'::jsonb, 2, 'Under IRC Section 6013(a)(3), an executor may elect to file a joint return with the surviving spouse for the year of death. This provides the MFJ standard deduction ($30,000 in 2025) and widest brackets. The key condition is that the surviving spouse has not remarried before year-end. QSS status applies in the two years following the year of death, not the year of death itself. The Code explicitly permits joint filing through the executor.', 'hard', 4),

-- Q20: hard / L4 — Scholarships excluded from self-support calculation
(3, 'Individual Taxation: Filing/Credits', 'Pierce, age 20 and a full-time college student, received a $25,000 scholarship covering tuition, earned $5,000 from a part-time job, and had total expenses of $35,000. Pierce''s parents provided $30,000 of support. Pierce spent all $5,000 of earnings on personal expenses. Evaluate whether Pierce meets the self-support test for a qualifying child and how the scholarship affects the calculation.', '["Pierce fails because her scholarship plus earnings of $30,000 cover more than half of her $35,000 expenses", "Pierce fails because her total resources exceed her parents'' $30,000 contribution", "Pierce passes because scholarships are treated as parental support rather than self-support", "Pierce passes because scholarships for tuition are excluded from the support calculation, and her $5,000 self-support is less than half of $35,000"]'::jsonb, 3, 'Under IRC Section 152(f)(5), scholarships received by a student are excluded from the support calculation for determining whether the child provided more than half of their own support. Excluding the $25,000 scholarship, Pierce provided only $5,000 of her own support out of $35,000 total (14%), well below 50%. A common error is including scholarship amounts in the child''s self-support, which would incorrectly make the child appear self-supporting.', 'hard', 4),

-- Q21: medium / L3 — In-law relationship survives spouse''s death
(3, 'Individual Taxation: Filing/Credits', 'Harris married into the Chen family in 2018. Harris''s spouse died in 2023, but Harris continued providing full support for his mother-in-law, Mrs. Chen, who lives alone in a separate apartment. Mrs. Chen''s only income is $3,500 from a pension. Analyze whether Harris can continue claiming Mrs. Chen as a qualifying relative after his spouse''s death.', '["Yes, because in-law relationships established by marriage survive the death of the spouse who created the connection", "No, because the death of Harris''s spouse terminates the in-law relationship for dependency purposes", "Yes, but only for two years following the spouse''s death, matching the QSS window", "No, because Mrs. Chen must live with Harris to be claimed as a qualifying relative"]'::jsonb, 0, 'Under IRC Section 152(d)(2)(G) and Treasury Regulation Section 1.152-2(d), in-law relationships are not terminated by death or divorce. Harris can continue claiming Mrs. Chen because the relationship persists, her gross income ($3,500) is below $5,050, and he provides over 50% support. As a parent-type relative, she does not need to live with Harris. A common error is assuming in-law status ends when the connecting spouse dies.', 'medium', 3),

-- Q22: easy / L1 — Expenses included in cost of maintaining a home for HOH
(3, 'Individual Taxation: Filing/Credits', 'Which expense is included in the cost of maintaining a home for Head of Household purposes?', '["Clothing for household members", "Utilities such as electricity and gas", "Medical care for the qualifying person", "Transportation costs for commuting"]'::jsonb, 1, 'Under IRC Section 2(b), the cost of maintaining a home includes rent, mortgage interest, property taxes, insurance, repairs, utilities, and food consumed in the home. Clothing, education, medical care, life insurance, and transportation are not counted. Utilities like electricity and gas are direct home-maintenance costs. A common exam error is including personal expenses like clothing or medical bills in the home-cost calculation.', 'easy', 1),

-- Q23: easy / L1 — Education credits denied under MFS
(3, 'Individual Taxation: Filing/Credits', 'Which filing status makes a taxpayer ineligible for both the AOTC and the Lifetime Learning Credit?', '["Single", "Head of Household", "Married Filing Separately", "Qualifying Surviving Spouse"]'::jsonb, 2, 'Under IRC Section 25A(g)(6), taxpayers who file as Married Filing Separately are ineligible for both the American Opportunity Tax Credit and the Lifetime Learning Credit. All other filing statuses — Single, HOH, MFJ, and QSS — permit education credits subject to AGI phase-outs. This rule is one of several restrictions associated with MFS status.', 'easy', 1),

-- Q24: hard / L3 — Lifetime Learning Credit vs AOTC for graduate student
(3, 'Individual Taxation: Filing/Credits', 'Reeves is a fifth-year graduate student pursuing a master''s degree. She previously claimed the AOTC for four undergraduate years. Her 2025 qualified education expenses total $8,000, and her AGI is $55,000 (Single). Analyze which education credit is available and calculate its amount.', '["AOTC of $2,500, because the four-year limit resets for graduate programs", "AOTC of $2,000, because graduate studies receive a reduced credit rate", "LLC of $2,500, because the LLC matches the AOTC maximum for graduate students", "LLC of $1,600, because the AOTC is limited to the first four years and the LLC provides 20% of up to $10,000 in expenses"]'::jsonb, 3, 'Under IRC Section 25A(b)(2), the AOTC is limited to the first four tax years of postsecondary education. Since Reeves already claimed it for four undergraduate years, she cannot claim it for graduate school. Under Section 25A(c), the Lifetime Learning Credit provides 20% of the first $10,000 in qualified expenses. With $8,000 in expenses, the LLC is $1,600 (20% x $8,000). The AOTC four-year limit does not reset for a new degree program.', 'hard', 3),

-- Q25: medium / L2 — Dependent''s standard deduction formula
(3, 'Individual Taxation: Filing/Credits', 'Powell, age 17 and claimed as a dependent, earned $4,200 from a summer job and received $600 in interest income during 2025. Powell files as Single. Under the dependent standard deduction formula, what is Powell''s standard deduction?', '["$4,650", "$4,200", "$1,350", "$15,000"]'::jsonb, 0, 'Under IRC Section 63(c)(5), a dependent''s standard deduction is the greater of $1,350 or earned income plus $450, capped at the regular standard deduction. Powell''s earned income of $4,200 plus $450 equals $4,650, which exceeds $1,350. Since $4,650 is below $15,000, the standard deduction is $4,650. A common error is using only the earned income ($4,200) without the $450 addition, or defaulting to the full $15,000.', 'medium', 2),

-- Q26: easy / L1 — QSS requires dependent child at home
(3, 'Individual Taxation: Filing/Credits', 'Qualifying Surviving Spouse status requires maintaining a home as the principal residence of which type of dependent for the entire year?', '["Any qualifying relative", "A dependent child such as a son, daughter, or stepchild", "The deceased spouse''s parent", "Any person related to the deceased spouse"]'::jsonb, 1, 'Under IRC Section 2(a)(1)(B), Qualifying Surviving Spouse status requires the taxpayer to maintain a home that is the principal place of abode for a dependent child — specifically a son, daughter, or stepchild — for the entire tax year. Other dependents such as parents, siblings, or qualifying relatives do not satisfy this requirement. QSS is targeted at widowed parents raising children in the household.', 'easy', 1),

-- Q27: easy / L1 — Additional standard deduction amount for unmarried 65+
(3, 'Individual Taxation: Filing/Credits', 'For 2025, what is the additional standard deduction amount for an unmarried taxpayer who is age 65 or older?', '["$1,600", "$1,350", "$2,000", "$2,500"]'::jsonb, 2, 'Under IRC Section 63(f), the additional standard deduction for 2025 is $2,000 for each qualifying condition (age 65+ or blind) for unmarried taxpayers filing Single or Head of Household. Married taxpayers receive $1,600 per condition. The $2,000 amount reflects the higher standard afforded to unmarried seniors. A common error is confusing the unmarried amount ($2,000) with the married amount ($1,600).', 'easy', 1),

-- Q28: medium / L2 — Other Dependents Credit ($500) for child age 17+
(3, 'Individual Taxation: Filing/Credits', 'The Nguyen family (MFJ, AGI $120,000) has two children: a 10-year-old son who qualifies for the Child Tax Credit and a 17-year-old daughter who is claimed as a qualifying child dependent. Under Section 24, what is their total credit for both children?', '["$4,000 ($2,000 per child regardless of age)", "$2,000 (credit for the son only; no credit for the 17-year-old)", "$3,000 ($2,000 for the son plus $1,000 for the daughter)", "$2,500 ($2,000 Child Tax Credit for the son plus $500 Other Dependents Credit for the daughter)"]'::jsonb, 3, 'Under IRC Section 24(h)(4), qualifying dependents not eligible for the $2,000 Child Tax Credit — including children age 17 or older — may qualify for the $500 Other Dependents Credit. The 10-year-old qualifies for the $2,000 CTC because he is under 17. The 17-year-old exceeds the CTC age limit but qualifies for the $500 credit as a dependent. Total: $2,500. A common error is assuming no credit exists for dependents 17 and older.', 'medium', 2),

-- Q29: hard / L4 — Adoption credit for special needs child (full amount regardless of expenses)
(3, 'Individual Taxation: Filing/Credits', 'Dawson and Lee (MFJ, AGI $190,000) finalized the adoption of a U.S. special needs child in 2025. They incurred only $8,000 in qualified adoption expenses. The maximum Section 23 adoption credit for 2025 is $16,810. Evaluate the credit amount the couple may claim.', '["$16,810, because a special needs adoption entitles the taxpayer to the full maximum credit regardless of actual expenses incurred", "$8,000, because the credit is limited to actual qualified adoption expenses paid", "$12,405, because the credit is reduced proportionally based on the ratio of expenses to the maximum", "$0, because their AGI of $190,000 exceeds the income limit for the adoption credit"]'::jsonb, 0, 'Under IRC Section 23(a)(3), taxpayers who adopt a U.S. child with special needs are deemed to have paid qualified adoption expenses equal to the maximum credit amount, regardless of actual expenses. This ensures families adopting special needs children receive the full benefit. For non-special-needs adoptions the credit is limited to actual expenses up to the maximum. A common error is capping the credit at the $8,000 actually spent.', 'hard', 4),

-- Q30: easy / L1 — Tiebreaker default: parent wins over non-parent
(3, 'Individual Taxation: Filing/Credits', 'Under the dependency tiebreaker rules, who has priority when a parent and a non-parent both claim the same qualifying child?', '["The taxpayer with the higher adjusted gross income", "The parent, regardless of adjusted gross income", "The taxpayer who provides more than 50% of the child''s support", "The taxpayer who has the child in the home for more nights"]'::jsonb, 1, 'Under IRC Section 152(c)(4)(A), the tiebreaker rules give priority to the parent over any non-parent when both are eligible to claim a qualifying child. AGI does not determine the outcome when a parent competes with a non-parent. The higher-AGI rule applies only between two non-parents, or between two parents who had the child for equal periods. Parent priority always takes precedence.', 'easy', 1)
;

COMMIT;
